//! Canonical post-stack head parity.
//!
//! Validates the NAMCore multi-stage post-stack head contract
//! (`config.head.kernel_sizes`) against three independent references:
//!
//! 1. the production f32 engine without prewarm vs the NumPy f64 anchor,
//! 2. the Rust f64 reference oracle vs the same NumPy f64 anchor,
//! 3. the live pinned `namcore_render` (C++) vs the prewarmed Rust engine.
//!
//! Fixtures are generated by `tests/fixtures/generate_post_stack_head_fixtures.py`
//! and deliberately cover one/multiple stages, intermediate widths distinct
//! from the final `out_channels`, implicit biases, non-linear activations and
//! a negative `head_scale`.

use super::common::*;
use neural_amp_modeler_rs::loader::dispatcher::build_model;
use neural_amp_modeler_rs::loader::nam_json::parse::parse_nam_json;
use neural_amp_modeler_rs::loader::nam_json::{WavenetTopologyResult, get_wavenet_topology};
use neural_amp_modeler_rs::models::NamModel;
use neural_amp_modeler_rs::testing::reference_oracle::{
    PrecisionConfig, compute_esr_f64, esr_to_db_f64, oracle_forward,
};
use neural_amp_modeler_rs::testing::wav::{read_wav_f32, write_wav_f32};

use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::Command;

use crate::common::alloc_audit::{TrackingGuard, get_alloc_count};

const FIXTURES: [(&str, &[usize]); 3] = [
    ("wavenet_post_head_k13", &[1, 3]),
    ("wavenet_post_head_single_k3", &[3]),
    ("wavenet_post_head_multistage", &[3, 1, 3]),
];

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

fn models_dir() -> PathBuf {
    fixtures_dir().join("models")
}

fn anchors_dir() -> PathBuf {
    fixtures_dir().join("f64_anchors")
}

fn load_f64_binary(path: &Path) -> Vec<f64> {
    let mut f = fs::File::open(path).expect("open f64 binary");
    let mut buf = [0u8; 4];
    f.read_exact(&mut buf).expect("read count");
    let n = u32::from_le_bytes(buf) as usize;
    let mut data = Vec::with_capacity(n);
    let mut sample = [0u8; 8];
    for _ in 0..n {
        f.read_exact(&mut sample).expect("read sample");
        data.push(f64::from_le_bytes(sample));
    }
    data
}

fn find_namcore_render_bin() -> Option<PathBuf> {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    [
        manifest_dir.join("build/namcore_render/tools/render"),
        manifest_dir.join("build/namcore_render/Release/render"),
        manifest_dir.join("build/namcore_render/Debug/render"),
        manifest_dir.join("build/namcore_render/render"),
    ]
    .into_iter()
    .find(|p| p.is_file())
}

fn process_in_blocks(model: &mut dyn NamModel, input: &[f32], output: &mut [f32]) {
    let mut pos = 0;
    while pos < input.len() {
        let end = (pos + 64).min(input.len());
        model.process(&input[pos..end], &mut output[pos..end]);
        pos = end;
    }
}

#[test]
fn test_post_stack_head_rf_contract() {
    for (name, kernels) in FIXTURES {
        let json = fs::read_to_string(models_dir().join(format!("{name}.nam")))
            .expect("read post-stack head fixture");
        let data = parse_nam_json(&json).expect("parse fixture");
        let head = data
            .config
            .parse_head()
            .unwrap_or_else(|| panic!("{name}: config.head must parse"));

        assert_eq!(head.resolved_kernel_sizes(), kernels, "{name}");
        let expected_rf = 1 + kernels.iter().map(|k| k - 1).sum::<usize>();
        assert_eq!(head.receptive_field(), expected_rf, "{name}: head RF");
    }
}

#[test]
fn test_post_stack_head_engine_matches_f64_anchor() {
    let input_f64 = load_f64_binary(&anchors_dir().join("post_stack_head_256_input.bin"));
    let input: Vec<f32> = input_f64.iter().map(|&v| v as f32).collect();

    for (name, _) in FIXTURES {
        let path = models_dir().join(format!("{name}.nam"));
        let data =
            parse_nam_json(&fs::read_to_string(&path).expect("read model")).expect("parse model");
        let mut model = build_model(&data).expect("build model");

        // Zero-state engine output (no prewarm) vs the f64 zero-history anchor.
        let mut output = vec![0.0f32; input.len()];
        process_in_blocks(model.as_mut(), &input, &mut output);

        let anchor = load_f64_binary(&anchors_dir().join(format!("{name}_256_f64.bin")));
        let output_f64: Vec<f64> = output.iter().map(|&v| v as f64).collect();
        let esr = compute_esr_f64(&output_f64, &anchor);
        eprintln!(
            "[PostHead] {name}: engine f32 vs NumPy f64 ESR={esr:.3e} ({:.1} dB)",
            esr_to_db_f64(esr)
        );
        assert!(esr < 1e-9, "{name}: engine/f64 ESR {esr:.3e} exceeds 1e-9");
    }
}

#[test]
fn test_post_stack_head_rust_oracle_matches_python_anchor() {
    let input = load_f64_binary(&anchors_dir().join("post_stack_head_256_input.bin"));

    for (name, _) in FIXTURES {
        let path = models_dir().join(format!("{name}.nam"));
        let data =
            parse_nam_json(&fs::read_to_string(&path).expect("read model")).expect("parse model");
        let oracle = oracle_forward(&data, &input, &PrecisionConfig::default());
        let anchor = load_f64_binary(&anchors_dir().join(format!("{name}_256_f64.bin")));
        let esr = compute_esr_f64(&oracle, &anchor);
        eprintln!(
            "[PostHead] {name}: Rust f64 oracle vs NumPy anchor ESR={esr:.3e} ({:.1} dB)",
            esr_to_db_f64(esr)
        );
        assert!(
            esr < 1e-12,
            "{name}: Rust oracle/Python anchor ESR {esr:.3e} exceeds 1e-12"
        );
    }
}

#[test]
fn test_post_stack_head_live_cpp_parity() {
    let Some(render_bin) = find_namcore_render_bin() else {
        eprintln!("[STATUS] SKIP_OPTIONAL_FIXTURE: namcore_render not found");
        return;
    };

    let input_f64 = load_f64_binary(&anchors_dir().join("post_stack_head_256_input.bin"));
    let input: Vec<f32> = input_f64.iter().map(|&v| v as f32).collect();
    let tmp = std::env::temp_dir();
    let in_wav = tmp.join("nam_post_stack_head_in.wav");
    write_wav_f32(&in_wav, &input, 48000).expect("write input wav");

    for (name, _) in FIXTURES {
        let model_path = models_dir().join(format!("{name}.nam"));
        let out_wav = tmp.join(format!("nam_post_stack_head_{name}_cpp.wav"));
        let status = Command::new(&render_bin)
            .arg(&model_path)
            .arg(&in_wav)
            .arg(&out_wav)
            .output()
            .expect("run namcore_render");
        assert!(
            status.status.success(),
            "{name}: C++ render failed: {}",
            String::from_utf8_lossy(&status.stderr)
        );
        let (cpp, cpp_sr) = read_wav_f32(&out_wav).expect("read C++ output");
        assert_eq!(cpp_sr, 48000);
        assert_eq!(cpp.len(), input.len());

        let data = parse_nam_json(&fs::read_to_string(&model_path).expect("read model"))
            .expect("parse model");
        let mut model = build_model(&data).expect("build model");
        model.prewarm(2048);
        let mut rust = vec![0.0f32; input.len()];
        process_in_blocks(model.as_mut(), &input, &mut rust);

        // The anchor/engine store starts from zero history while both
        // production paths prewarm; compare after the head transient.
        let start = 64;
        let esr = compute_esr(&cpp[start..], &rust[start..]);
        let snr = if esr > 0.0 {
            10.0 * (1.0 / esr).log10()
        } else {
            f64::INFINITY
        };
        eprintln!("[PostHead] {name}: C++ vs Rust ESR={esr:.3e}, SNR={snr:.1} dB");
        assert!(esr < 1e-8, "{name}: C++/Rust ESR {esr:.3e} exceeds 1e-8");
        assert!(snr > 70.0, "{name}: C++/Rust SNR {snr:.1} dB below 70");
    }
}

#[test]
fn test_post_stack_head_block_invariance_and_reset() {
    let input_f64 = load_f64_binary(&anchors_dir().join("post_stack_head_256_input.bin"));
    let input: Vec<f32> = input_f64.iter().map(|&v| v as f32).collect();

    for (name, _) in FIXTURES {
        let path = models_dir().join(format!("{name}.nam"));
        let data =
            parse_nam_json(&fs::read_to_string(&path).expect("read model")).expect("parse model");
        let mut model = build_model(&data).expect("build model");
        model.prewarm(2048);

        let mut whole = vec![0.0f32; input.len()];
        model.process(&input, &mut whole);

        model.reset(48000, 64).expect("reset before blocked run");
        let mut blocked = vec![0.0f32; input.len()];
        let mut pos = 0;
        while pos < input.len() {
            let end = (pos + 1).min(input.len());
            model.process(&input[pos..end], &mut blocked[pos..end]);
            pos = end;
        }
        let block_esr = compute_esr(&whole, &blocked);
        eprintln!("[PostHead] {name}: block-size invariance ESR={block_esr:.3e}");
        assert!(
            block_esr < 1e-10,
            "{name}: block-size invariance ESR {block_esr:.3e}"
        );

        model.reset(48000, 64).expect("reset");
        let mut after_reset = vec![0.0f32; input.len()];
        process_in_blocks(model.as_mut(), &input, &mut after_reset);
        let esr = compute_esr(&whole, &after_reset);
        eprintln!("[PostHead] {name}: reset repeatability ESR={esr:.3e}");
        assert!(esr < 1e-12, "{name}: reset ESR {esr:.3e}");
    }
}

#[test]
fn test_post_stack_head_zero_alloc_hot_path() {
    let path = models_dir().join("wavenet_post_head_k13.nam");
    let data = parse_nam_json(&fs::read_to_string(path).expect("read model")).expect("parse");
    let mut model = build_model(&data).expect("build model");
    model.prewarm(2048);

    let input = generate_sine_440hz(64);
    let mut output = vec![0.0f32; 64];

    {
        let _guard = TrackingGuard::new();
        model.process(&input, &mut output);
    }

    assert_eq!(
        get_alloc_count(),
        0,
        "canonical post-stack head allocated in the process() hot path"
    );
}

#[test]
fn test_post_stack_head_invalid_configs_fail_closed() {
    let base =
        fs::read_to_string(models_dir().join("wavenet_post_head_k13.nam")).expect("read fixture");

    let cases: [(&str, serde_json::Value); 4] = [
        (
            "empty kernel_sizes",
            serde_json::json!({"channels": 4, "out_channels": 1, "kernel_sizes": [], "activation": "Tanh"}),
        ),
        (
            "zero kernel",
            serde_json::json!({"channels": 4, "out_channels": 1, "kernel_sizes": [0], "activation": "Tanh"}),
        ),
        (
            "oversized kernel",
            serde_json::json!({"channels": 4, "out_channels": 1, "kernel_sizes": [17], "activation": "Tanh"}),
        ),
        (
            "ambiguous kernel fields",
            serde_json::json!({"channels": 4, "out_channels": 1, "kernel_sizes": [1, 3], "kernel_size": 3, "activation": "Tanh"}),
        ),
    ];

    let mut non_object: serde_json::Value =
        serde_json::from_str(&base).expect("parse fixture json");
    non_object["config"]["head"] = serde_json::json!([]);
    let parsed = parse_nam_json(&non_object.to_string()).expect("JSON syntax is valid");
    assert!(
        matches!(
            get_wavenet_topology(&parsed),
            WavenetTopologyResult::Rejected { .. }
        ),
        "non-object head must be rejected fail-closed"
    );

    for (label, head) in cases {
        let mut value: serde_json::Value = serde_json::from_str(&base).expect("parse fixture json");
        value["config"]["head"] = head;
        let parsed = parse_nam_json(&value.to_string()).expect("JSON syntax is valid");
        match get_wavenet_topology(&parsed) {
            WavenetTopologyResult::Rejected { .. } => {}
            other => panic!("{label} must be rejected fail-closed, got {other:?}"),
        }
        assert!(build_model(&parsed).is_err(), "{label}: build must fail");
    }
}
